thread_local! {
    static API: RefCell<Option<Box<dyn WndMgrApi>>> = const { RefCell::new(None) };
}

/// Installs the implementation (call on the Python thread before the interpreter runs scripts).
pub fn set_api(api: Box<dyn WndMgrApi>) {
    API.with(|a| *a.borrow_mut() = Some(api));
}

fn with_api<R>(f: impl FnOnce(&mut dyn WndMgrApi) -> R) -> Option<R> {
    API.with(|a| a.borrow_mut().as_mut().map(|b| f(b.as_mut())))
}

/// C entry point for `wndMgr.ActivateSlot(win: handle:window, slot_index: int) -> none`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn m2_wnd_mgr_activate_slot(win: usize, slot_index: i32) -> M2Result {
    match with_api(|api| api.activate_slot(win, slot_index)) {
        None => no_api("wndMgr"),
        Some(Err(e)) => fail(e),
        Some(Ok(_v)) => {
            
            ok()
        }
    }
}

